import {sqliteTable,text,integer,index,uniqueIndex} from 'drizzle-orm/sqlite-core';
export const records=sqliteTable('records',{id:text('id').primaryKey(),kind:text('kind').notNull(),owner:text('owner').notNull(),data:text('data').notNull(),created:text('created').notNull() },t=>[index('records_kind_owner').on(t.kind,t.owner)]);
export const bookings=sqliteTable('bookings',{id:text('id').primaryKey(),owner:text('owner').notNull(),tour:text('tour').notNull(),date:text('date').notNull(),guests:integer('guests').notNull(),total:integer('total').notNull(),status:text('status').notNull(),token:text('token').notNull(),data:text('data').notNull(),created:text('created').notNull(),requestKey:text('request_key').notNull()},t=>[index('bookings_owner').on(t.owner),uniqueIndex('bookings_token').on(t.token),uniqueIndex('bookings_request').on(t.owner,t.requestKey)]);
export const settings=sqliteTable('settings',{key:text('key').primaryKey(),value:text('value').notNull()});
export const sessions=sqliteTable('sessions',{token:text('token').primaryKey(),owner:text('owner').notNull(),role:text('role').notNull(),expires:integer('expires').notNull()});
export const discoveryTerms=sqliteTable('discovery_terms',{id:text('id').primaryKey(),kind:text('kind').notNull(),data:text('data').notNull(),updated:text('updated').notNull()},t=>[index('discovery_terms_kind').on(t.kind)]);
export const discoveryLinks=sqliteTable('discovery_links',{id:text('id').primaryKey(),tour:text('tour').notNull(),term:text('term').notNull()},t=>[uniqueIndex('discovery_links_tour_term').on(t.tour,t.term),index('discovery_links_term_tour').on(t.term,t.tour)]);
